effect.script:
function pingpong(x){
let f = x - Math.floor(x);
if( f < 0.5 ) return f * 2.0;
return (1.0 - f) * 2.0;
}

function animate(env, el, p){
let base = el.text;
let n = base.length;
if( n < 1 ) return el;

// ---- gap character ------------------------------------------------------
let gc = " ";
let g = Math.round(p.gapChar);
if( g < 1 ) gc = " ";
else if( g < 2 ) gc = "\u00B7";
else if( g < 3 ) gc = "-";
else if( g < 4 ) gc = "\u2022";
else if( g < 5 ) gc = "/";
else if( g < 6 ) gc = "|";
else if( g < 7 ) gc = "*";
else gc = "\u25AA";

let gn = Math.max(0, Math.round(p.gap));
let gap = "";
for( let k = 0; k < gn; k = k + 1 ){ gap = gap + gc; }

// The ring is the line plus its gap. Everything downstream is measured in
// characters on this ring, which is why the scroll can never run dry.
let ring = base + gap;
let rn = ring.length;
if( rn < 1 ) return el;

// ---- clock --------------------------------------------------------------
let t;
if( Math.round(p.timeSource) < 1 ){ t = env.time * env.duration; }
else { t = env.absTime; }

let rev = Math.round(p.direction) > 0;
let spd = rev ? -p.speed : p.speed;

let md = Math.round(p.mode);
let pos = 0.0;
if( md < 1 ){
// Loop - the ring wraps forever.
pos = t * spd + p.phase;
pos = pos - Math.floor(pos);
pos = pos * rn;
} else if( md < 2 ){
// Ping-Pong - runs out, comes back, no seam at either end.
pos = pingpong(t * spd + p.phase) * rn;
} else {
// Reveal Once - one pass, then hold.
let dur = Math.max(1e-3, p.travel);
let u = t / dur;
if( u > 1.0 ) u = 1.0;
if( u < 0.0 ) u = 0.0;
let hd = Math.max(0.0, p.hold);
pos = u * (1.0 + hd) * rn;
if( rev ){ pos = -pos; }
}

// ---- window -------------------------------------------------------------
let win = Math.max(0.02, Math.min(1.0, p.window));
let vis = Math.max(1, Math.round(n * win));

let anc = Math.round(p.anchor);
pos = pos + anc * 0.5 * vis;

// Repeat the ring enough times that a full window is always available, then
// slice - no padding, no short last frame.
let reps = Math.ceil((vis + rn + 4) / rn) + 1;
let big = "";
for( let k = 0; k < reps; k = k + 1 ){ big = big + ring; }

let start = Math.floor(pos) % rn;
if( start < 0 ){ start = start + rn; }
let s = big.substr(start, vis);
while( s.length < vis ){ s = s + gc; }

// ---- type ---------------------------------------------------------------
let cm = Math.round(p.caseMode);
if( cm == 1 ){ s = s.toUpperCase(); }
else if( cm == 2 ){ s = s.toLowerCase(); }
if( p.trimSpaces ){
s = s.replace(/^\s+/, "").replace(/\s+$/, "");
}

el.text = s;
return el;
}
